import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == "Windows":
        command = ["start", url]
    elif system == "Darwin":
        command = ["open", url]
    else:
        command = ["xdg-open", url]
    process = subprocess.Popen(command)
    time.sleep(0.1)
    return_code = process.poll()
    if return_code is None:
        return 0
    else:
        return return_code

