import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"File not found: {script_path}")

    def run_script(proc, result):
        try:
            output, _ = proc.communicate()
            result['output'] = output.decode('utf-8') if output else ''
            result['returncode'] = proc.returncode
        except Exception as e:
            result['error'] = str(e)

    process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    result = {}
    thread = threading.Thread(target=run_script, args=(process, result))
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        process.terminate()
        thread.join()
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

